/// The running build number, as the window hands it to `aterm_update`.
#[must_use]
pub fn running_build_number() -> u64 {
    build_info::build_number().parse::<u64>().unwrap_or(0)
}

pub use update_words::DevSharedWrites;

fn running_install_posture() -> Option<aterm_update::which_copy::InstallPosture> {
    #[cfg(all(target_os = "macos", not(test)))]
    {
        aterm_update::which_copy::running_posture()
    }
    #[cfg(not(all(target_os = "macos", not(test))))]
    {
        None
    }
}

/// What this copy writes of the shared user state only the release writes unattended, in words (`update_words::dev_shared_writes`).
#[must_use]
pub fn dev_build_shared_writes() -> Option<DevSharedWrites> {
    update_words::dev_shared_writes(
        atpkg::hooks::runs_from_non_release_bundle(),
        co_located_atpkg().is_some() && atpkg::config::load().enabled(),
        app_config::agents_auto_prime_setting(),
    )
}

/// Read-only compiled identity for the native updater and release worker.
#[must_use]
pub fn running_binary_identity() -> aterm_update_core::linux::BinaryIdentity {
    aterm_update_core::linux::BinaryIdentity {
        schema: 1,
        version: build_info::version().into(),
        build_number: running_build_number(),
        commit: build_info::git_commit_full().into(),
        target: build_info::BINARY_TARGET.into(),
        dirty: build_info::git_dirty() == "true",
    }
}

