fn is_safe_url(url: &str) -> bool {
    let u = url.trim();
    if u.is_empty() || u.bytes().any(|b| b.is_ascii_control() || b == b' ') {
        return false;
    }
    let l = u.to_ascii_lowercase();
    l.starts_with("http://") || l.starts_with("https://") || l.starts_with("mailto:")
}

fn find_url_span(chars: &[char], col: usize) -> Option<(String, usize, usize)> {
    let n = chars.len();
    let is_url = |c: char| c.is_ascii_alphanumeric() || "-._~:/?#[]@!$&'()*+,;=%".contains(c);
    let mut i = 0;
    while i < n {
        let s = &chars[i..];
        if s.starts_with(&['h', 't', 't', 'p', ':', '/', '/'])
            || s.starts_with(&['h', 't', 't', 'p', 's', ':', '/', '/'])
        {
            let mut j = i;
            while j < n && is_url(chars[j]) {
                j += 1;
            }
            let mut end = j;
            while end > i
                && matches!(
                    chars[end - 1],
                    '.' | ',' | ';' | ':' | '!' | '?' | ')' | ']' | '\'' | '"'
                )
            {
                end -= 1;
            }
            if (i..end).contains(&col) {
                return Some((chars[i..end].iter().collect(), i, end - 1));
            }
            i = j.max(i + 1);
        } else {
            i += 1;
        }
    }
    None
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct PlainUrl {
    url: String,
    faint: bool,
}

const FAINT_URL_CONTRAST: f32 = 3.0;

fn plain_url_at(cells: &[RenderCell], col: usize, min_contrast: f32) -> Option<PlainUrl> {
    let ink = |cell: &RenderCell| {
        let bg = aterm_render::rgb_to_u32(cell.bg);
        let fg = aterm_render::rgb_to_u32(cell.fg);
        let painted = aterm_render::floor_min_contrast_fg(fg, bg, min_contrast);
        (painted, bg)
    };
    let mut chars: Vec<char> = cells
        .iter()
        .map(|c| if c.wide { ' ' } else { c.ch })
        .collect();
    let (_, start, end) = find_url_span(&chars, col)?;
    for (ch, cell) in chars[start..=end].iter_mut().zip(&cells[start..=end]) {
        let (fg, bg) = ink(cell);
        if fg == bg {
            *ch = ' ';
        }
    }
    let (url, start, end) = find_url_span(&chars, col)?;
    let faint = cells[start..=end]
        .iter()
        .map(ink)
        .any(|(fg, bg)| aterm_render::floor_fg_contrast(fg, bg, FAINT_URL_CONTRAST) != fg);
    Some(PlainUrl { url, faint })
}

fn plain_path_at(
    cells: &[RenderCell],
    col: usize,
    min_contrast: f32,
) -> Option<path_link::PathSpan> {
    let chars: Vec<char> = cells
        .iter()
        .map(|cell| {
            if cell.wide {
                return path_link::WIDE_CONTINUATION;
            }
            let bg = aterm_render::rgb_to_u32(cell.bg);
            let fg = aterm_render::rgb_to_u32(cell.fg);
            if aterm_render::floor_min_contrast_fg(fg, bg, min_contrast) == bg {
                ' '
            } else {
                cell.ch
            }
        })
        .collect();
    path_link::find_path_span(&chars, col)
}

/// The GUI's default font family, tried ahead of the library's `FONT_CANDIDATES`.
pub(crate) const fn default_font_family() -> Option<&'static str> {
    None
}

/// The effective font family.
pub(crate) fn effective_font_family(config_family: Option<&str>) -> Option<String> {
    effective_font_family_with(launch::flags().font_family.as_deref(), config_family)
}

/// [`effective_font_family`] with `flag` standing in for `--font`.
pub(crate) fn effective_font_family_with(
    flag: Option<&str>,
    config_family: Option<&str>,
) -> Option<String> {
    flag.filter(|family| aterm_render::display_face_ids_for_family(family).is_none())
        .map(str::to_string)
        .or_else(|| config_family.map(str::to_string))
        .or_else(|| default_font_family().map(str::to_string))
}

/// The effective display layer.
pub(crate) fn effective_display_faces(config: &app_config::Config) -> Vec<&'static str> {
    launch::flags()
        .font_family
        .as_deref()
        .and_then(aterm_render::display_face_ids_for_family)
        .map(aterm_render::display_layer_ids)
        .unwrap_or_else(|| config.display_faces_request())
}

/// Interior padding at scale 1.0 (logical px) between the window edge and the grid, scaled by the display scale factor (`round(12·scale)`).
pub(crate) const PAD_LOGICAL_PX: f32 = 12.0;

fn pad_for_scale(scale: f64) -> usize {
    logical_to_device_px(PAD_LOGICAL_PX, scale)
}

/// Top interior padding at scale 1.0 (logical px), small because the chrome `head` band already separates the grid from the top edge.
pub(crate) const PAD_TOP_LOGICAL_PX: f32 = 2.0;

fn pad_top_for_scale(scale: f64) -> usize {
    logical_to_device_px(PAD_TOP_LOGICAL_PX, scale)
}

/// A logical-px length in device px at `scale`.
pub(crate) fn logical_to_device_px(logical: f32, scale: f64) -> usize {
    (logical * scale as f32).round().max(0.0) as usize
}

fn headroom_override() -> usize {
    static HEADROOM: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *HEADROOM.get_or_init(|| {
        aterm_types::dev_seam!("ATERM_DEV_HEADROOM_PX")
            .and_then(|v| v.to_str()?.trim().parse::<usize>().ok())
            .unwrap_or(0)
    })
}

fn seed_cell_px(px: f32) -> (usize, usize) {
    (
        (px * 0.6).round().max(1.0) as usize,
        (px * 1.2).round().max(1.0) as usize,
    )
}

/// The device px a font `size` (px at 1×, the one font-size unit) draws at on a display of `scale`.
pub(crate) fn font_px_for_scale(size: f32, scale: f64) -> f32 {
    let px = if scale.is_finite() && scale > 0.0 && (scale - 1.0).abs() > f64::EPSILON {
        (size * scale as f32).round()
    } else {
        size
    };
    if px.is_finite() {
        px.clamp(FONT_PX_MIN, FONT_PX_MAX)
    } else {
        FONT_PX
    }
}

/// A DEFAULT or configured font size (px at 1×) scaled by the text size scale (`font_size_scale`, in thousandths).
pub(crate) fn scaled_font_px(px: f32, scale_milli: u16) -> f32 {
    if scale_milli == 1000 {
        px
    } else {
        (px * f32::from(scale_milli) / 1000.0)
            .round()
            .clamp(FONT_PX_MIN, FONT_PX_MAX)
    }
}

/// Per-window font size and padding from the window's own scale factor (mixed DPI).
#[derive(Clone, Copy, Debug, PartialEq)]
pub(crate) struct MetricsView {
    pub font_px: f32,
    pub pad: usize,
    pub pad_top: usize,
    pub head: usize,
}

impl MetricsView {
    /// The default metrics for a display `scale`.
    #[cfg(test)]
    pub(crate) fn for_scale(scale: f64) -> Self {
        Self::for_scale_padded(FONT_PX, scale, PAD_LOGICAL_PX, PAD_TOP_LOGICAL_PX)
    }

    /// The metrics of a window of `scale` at font `size` (px at 1×, already carrying the text size scale).
    pub(crate) fn for_scale_padded(
        size: f32,
        scale: f64,
        pad_logical: f32,
        pad_top_logical: f32,
    ) -> Self {
        let pad = logical_to_device_px(pad_logical, scale);
        MetricsView {
            font_px: font_px_for_scale(size, scale),
            pad,
            pad_top: clamp_visible_pad_top(pad, logical_to_device_px(pad_top_logical, scale)),
            head: 0,
        }
    }

    /// A window's actual metrics.
    pub(crate) fn applied(font_px: f32, pad: usize, pad_top: usize, head: usize) -> Self {
        MetricsView {
            font_px,
            pad,
            pad_top: clamp_visible_pad_top(pad, pad_top),
            head,
        }
    }
}

const BLINK_INTERVAL: Duration = Duration::from_millis(530);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct StaleBlinkRoll {
    next: Instant,
    phase_flips: bool,
}

fn roll_stale_blink_forward(deadline: Instant, now: Instant) -> Option<StaleBlinkRoll> {
    let overdue = now.checked_duration_since(deadline)?;
    if overdue < BLINK_INTERVAL {
        return None;
    }
    let missed = overdue.as_nanos() / BLINK_INTERVAL.as_nanos().max(1);
    let flips = u32::try_from(missed.saturating_add(1)).unwrap_or(u32::MAX);
    let next = deadline
        .checked_add(BLINK_INTERVAL.saturating_mul(flips))
        .unwrap_or(now + BLINK_INTERVAL);
    Some(StaleBlinkRoll {
        next,
        phase_flips: flips % 2 == 1,
    })
}

#[cfg(test)]
mod blink_roll_tests {
    use super::*;

    #[test]
    fn a_stale_deadline_rolls_onto_the_grid_and_a_due_or_future_one_does_not() {
        let origin = Instant::now();
        assert_eq!(
            roll_stale_blink_forward(origin + BLINK_INTERVAL / 3, origin),
            None
        );
        assert_eq!(
            roll_stale_blink_forward(origin, origin + BLINK_INTERVAL / 2),
            None
        );
        for (late, next, flips) in [
            (BLINK_INTERVAL, 2, false),
            (BLINK_INTERVAL * 2 + BLINK_INTERVAL / 2, 3, true),
        ] {
            let roll = roll_stale_blink_forward(origin, origin + late).expect("stale");
            assert_eq!(roll.next, origin + BLINK_INTERVAL * next, "{late:?}");
            assert!(roll.next > origin + late, "{late:?}");
            assert_eq!(roll.phase_flips, flips, "{late:?}");
        }
    }
}

const SYNC_RELEASE_GRACE: Duration = Duration::from_millis(50);

const MIN_FRAME_INTERVAL: Duration = Duration::from_micros(8_000);

const AURORA_TICK_INTERVAL: Duration = Duration::from_micros(16_667);

const MIN_EFFECT_TICK_INTERVAL: Duration = Duration::from_micros(4_167);

fn effect_tick_interval(panel: Option<Duration>) -> Duration {
    match panel {
        Some(period) => period.max(MIN_EFFECT_TICK_INTERVAL),
        None => AURORA_TICK_INTERVAL,
    }
}

const EFFECT_PRESENT_PANEL_PERIODS: u32 = 2;

const EFFECT_LANE_PANEL_RATE_MIN_PERIOD: Duration = Duration::from_micros(16_600);

const EFFECT_LANE_PANEL_RATE_AT_60HZ: bool =
    cfg!(any(not(target_os = "macos"), target_arch = "x86_64"));

const EFFECT_LANE_ACQUIRE_PARK_NS: u64 = 4_000_000;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PresentQueue {
    Fifo(u32),
    NonBlocking,
    Cpu,
    Unknown,
}

const EFFECT_FIFO_BACKLOG_MAX: f64 = 0.25;

const CONTENT_FIFO_BACKLOG_MAX: f64 = 1.0;

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct FifoBacklog {
    level: f64,
    at: Option<Instant>,
    period: Duration,
}

fn effect_slot_after_fifo_drain(fresh: Instant, drained: Option<Instant>, cap: Instant) -> Instant {
    drained.map_or(fresh, |drained| fresh.max(drained.min(cap)))
}

fn content_floor_after_fifo_drain(
    floor: Duration,
    drained: Option<Instant>,
    last_content_present: Option<Instant>,
) -> Duration {
    match (drained, last_content_present) {
        (Some(drained), Some(last)) => floor.max(drained.saturating_duration_since(last)),
        _ => floor,
    }
}

impl FifoBacklog {
    fn level_at(&self, now: Instant) -> f64 {
        let Some(at) = self.at else {
            return 0.0;
        };
        let period = self.period.as_secs_f64();
        if period <= 0.0 {
            return 0.0;
        }
        let drained = now.saturating_duration_since(at).as_secs_f64() / period;
        (self.level - drained).max(0.0)
    }

    fn note_present(&mut self, at: Instant, period: Duration) {
        self.level = self.level_at(at) + 1.0;
        self.at = Some(at);
        self.period = period;
    }

    fn drained_to(&self, max: f64) -> Option<Instant> {
        let at = self.at?;
        (self.level > max).then(|| at + self.period.mul_f64(self.level - max))
    }
}

fn effect_present_panel_periods(panel: Option<Duration>) -> u32 {
    effect_present_panel_periods_with(panel, EFFECT_LANE_PANEL_RATE_AT_60HZ)
}

fn effect_present_panel_periods_with(panel: Option<Duration>, panel_rate_at_60hz: bool) -> u32 {
    match panel {
        Some(period) if panel_rate_at_60hz && period >= EFFECT_LANE_PANEL_RATE_MIN_PERIOD => 1,
        _ => EFFECT_PRESENT_PANEL_PERIODS,
    }
}

fn effect_present_interval(panel: Option<Duration>) -> Duration {
    effect_present_interval_with(panel, effect_present_panel_periods(panel))
}

fn effect_present_interval_with(panel: Option<Duration>, periods: u32) -> Duration {
    effect_tick_interval(panel) * periods.max(1)
}

const fn present_queue_admits_panel_rate(queue: PresentQueue) -> bool {
    match queue {
        PresentQueue::NonBlocking | PresentQueue::Unknown => true,
        PresentQueue::Fifo(queued) => queued >= 2,
        PresentQueue::Cpu => false,
    }
}

const DECO_ANIM_LEVEL_FRAMES: u32 = 4;

const EDR_REQUERY_INTERVAL: Duration = Duration::from_millis(250);

fn edr_requery_due(last: Option<Instant>, now: Instant, interval: Duration) -> bool {
    last.is_none_or(|t| now.duration_since(t) >= interval)
}

fn edr_refresh_due(
    surface_hdr: Option<bool>,
    last: Option<(Instant, bool)>,
    now: Instant,
    interval: Duration,
) -> bool {
    surface_hdr.is_some_and(|hdr| {
        (hdr && last.is_some_and(|(_, stamped_hdr)| !stamped_hdr))
            || edr_requery_due(last.map(|(at, _)| at), now, interval)
    })
}

const REFRESH_RATE_REREAD_INTERVAL: Duration = Duration::from_millis(250);

fn refresh_rate_read_due(
    same_monitor: bool,
    force_read: bool,
    last_read: Option<Instant>,
    now: Instant,
    interval: Duration,
) -> bool {
    force_read || !same_monitor || last_read.is_none_or(|t| now.duration_since(t) >= interval)
}

fn repick_gpu_surface_for_screen(
    backend: &mut BackendSlot,
    apprt: &platform::PlatformAppRt,
    window_colorspace: app_config::WindowColorspace,
    window_gpu: &mut aterm_gpu::WindowGpu,
    gpu_surface: &mut aterm_gpu::GpuSurface,
    window: &Window,
) {
    if gpu_surface.is_hdr() {
        return;
    }
    if let Some(gpu) = backend.gpu_mut()
        && gpu.upgrade_surface_for_screen(window_gpu, gpu_surface, window)
    {
        let effective_colorspace = apprt.window_set_surface_colorspace(
            window,
            crate::platform::resolve_surface_colorspace(window_colorspace, true),
        );
        window_gpu.set_capture_color_space(crate::platform::capture_space_after_surface_tag(
            effective_colorspace,
            window_gpu.capture_color_space(),
        ));
    }
}

const DEMO_TICK_INTERVAL: Duration = Duration::from_millis(33);

fn native_preview_deadline(
    now: Instant,
    current: Option<Instant>,
    animation: settings_preview::PreviewAnimation,
) -> Option<Instant> {
    match animation {
        settings_preview::PreviewAnimation::None => None,
        settings_preview::PreviewAnimation::Continuous => {
            let candidate = now + DEMO_TICK_INTERVAL;
            Some(
                current
                    .filter(|deadline| *deadline > now && *deadline <= candidate)
                    .unwrap_or(candidate),
            )
        }
        settings_preview::PreviewAnimation::BlinkEdge { after_ms } => {
            Some(now + Duration::from_millis(after_ms.max(1)))
        }
    }
}

const fn native_preview_may_tick(
    has_os_window: bool,
    focused: bool,
    recorded: bool,
    overlay_open: bool,
) -> bool {
    (recorded || (has_os_window && focused)) && !overlay_open
}

/// Whether an introspection capture may read compositor pixels after trying to present a staged native frame.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum CaptureAfterPresentDecision {
    Capture,
    Retry,
    FailClosed,
}

/// Maximum real present calls the native capture barrier makes.
pub(crate) const NATIVE_CAPTURE_PRESENT_ATTEMPT_LIMIT: u8 = 3;

/// Never authorize pixel capture after a dropped present.
pub(crate) const fn capture_after_present_decision(
    present_succeeded: bool,
    attempts: u8,
    attempt_limit: u8,
) -> CaptureAfterPresentDecision {
    if present_succeeded {
        CaptureAfterPresentDecision::Capture
    } else if attempts < attempt_limit {
        CaptureAfterPresentDecision::Retry
    } else {
        CaptureAfterPresentDecision::FailClosed
    }
}

/// The bounded capture barrier against an injected present attempt.
pub(crate) fn run_capture_present_barrier(
    attempt_limit: u8,
    mut present: impl FnMut() -> bool,
) -> bool {
    let mut attempts = 0;
    while attempts < attempt_limit {
        attempts += 1;
        match capture_after_present_decision(present(), attempts, attempt_limit) {
            CaptureAfterPresentDecision::Capture => return true,
            CaptureAfterPresentDecision::Retry => {}
            CaptureAfterPresentDecision::FailClosed => return false,
        }
    }
    false
}

/// Generation guard at the semantic-font worker's installation boundary.
pub(crate) const fn semantic_prewarm_result_is_current(
    current_generation: u64,
    result_generation: u64,
) -> bool {
    current_generation == result_generation
}

/// Whether the one-slot semantic-font queue still owns a committed renderer base after replacing a not-yet-started job.
#[must_use]
pub(crate) const fn semantic_prewarm_replacement_carries_base(
    new_has_base: bool,
    replaced_has_base: bool,
) -> bool {
    new_has_base || replaced_has_base
}

/// Whether scheduling an uncached semantic-font candidate must first move the active renderer into the candidate cache.
#[must_use]
pub(crate) const fn semantic_prewarm_cache_active_before_request(
    active_present: bool,
    active_ready: bool,
    candidate_matches: bool,
) -> bool {
    active_present && active_ready && !candidate_matches
}

/// Result disposition at the semantic-font worker's main-thread boundary.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum SemanticPrewarmResultDecision {
    IgnoreStaleGeneration,
    InstallCurrent,
    FailClosedCurrent,
    CacheSuperseded,
    IgnoreFailedSuperseded,
}

/// Classify one completed semantic-font job without touching renderer state.
#[must_use]
pub(crate) const fn semantic_prewarm_result_decision(
    current_generation: u64,
    requested_request: u64,
    result_generation: u64,
    result_request: u64,
    candidate_matches: bool,
    renderer_ready: bool,
) -> SemanticPrewarmResultDecision {
    if !semantic_prewarm_result_is_current(current_generation, result_generation) {
        SemanticPrewarmResultDecision::IgnoreStaleGeneration
    } else if result_request == requested_request && candidate_matches {
        if renderer_ready {
            SemanticPrewarmResultDecision::InstallCurrent
        } else {
            SemanticPrewarmResultDecision::FailClosedCurrent
        }
    } else if renderer_ready {
        SemanticPrewarmResultDecision::CacheSuperseded
    } else {
        SemanticPrewarmResultDecision::IgnoreFailedSuperseded
    }
}

