fn multi_click_window_is_the_system_double_click_time() {
    assert_eq!(multi_click_window(900), 900);
    assert_eq!(multi_click_window(200), 200);
    assert_eq!(multi_click_window(0), DEFAULT_MULTI_CLICK_MS);
}

