#[allow(
    clippy::large_enum_variant,
    reason = "held once per App for its lifetime; Gpu is the common path, so boxing it to shrink the rare Cpu fallback would add a per-frame indirection for a one-time few-KB saving"
)]
enum Backend {
    Cpu(Renderer),
    Gpu(GpuBackend),
}

fn require_explicit_capture_readback(captured: Result<Frame, String>) -> Result<Frame, String> {
    captured.map_err(|error| format!("GPU capture readback failed: {error}"))
}

struct GpuBackend {
    renderer: aterm_gpu::GpuRenderer,
    visible_pad_top: usize,
}

fn clamp_visible_pad_top(pad: usize, requested: usize) -> usize {
    requested.min(pad)
}

impl GpuBackend {
    fn new(renderer: aterm_gpu::GpuRenderer) -> Self {
        let visible_pad_top = renderer.pad_top();
        Self {
            renderer,
            visible_pad_top,
        }
    }

    fn set_pad(&mut self, pad: usize) {
        let changed = self.renderer.pad() != pad;
        self.renderer.set_pad(pad);
        if changed {
            // `Renderer::set_pad` starts a fresh symmetric regime on a real
            // change. Mirror that rule in the visible authority.
            self.visible_pad_top = pad;
        }
    }

    fn set_visible_pad_top(&mut self, pad_top: usize) {
        self.visible_pad_top = clamp_visible_pad_top(self.renderer.pad(), pad_top);
        let removed = self.renderer.pad().saturating_sub(self.visible_pad_top);
        self.renderer
            .set_pad_top(self.visible_pad_top + removed.div_ceil(2));
    }

    fn configure_visible_y(&mut self, raw_height: usize, destination_height: usize) -> usize {
        let crop_top = gpu_visible_crop_top(
            raw_height,
            destination_height,
            self.renderer.pad(),
            self.visible_pad_top,
        );
        self.renderer
            .set_pad_top(self.visible_pad_top.saturating_add(crop_top));
        crop_top
    }
}

impl std::ops::Deref for GpuBackend {
    type Target = aterm_gpu::GpuRenderer;

    fn deref(&self) -> &Self::Target {
        &self.renderer
    }
}

impl std::ops::DerefMut for GpuBackend {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.renderer
    }
}

const fn visible_frame_height(raw_height: usize, pad: usize, pad_top: usize) -> usize {
    raw_height.saturating_sub(pad.saturating_sub(pad_top))
}

fn gpu_visible_crop_top(
    raw_height: usize,
    destination_height: usize,
    pad: usize,
    pad_top: usize,
) -> usize {
    let visible_height = visible_frame_height(raw_height, pad, pad_top);
    let visible_offset = aterm_render::band_offset_y(destination_height, visible_height);
    let raw_offset = aterm_render::band_offset_y(destination_height, raw_height);
    let removed = raw_height.saturating_sub(visible_height);
    usize::try_from(visible_offset.saturating_sub(raw_offset))
        .unwrap_or(removed)
        .min(removed)
}

fn asymmetric_pad_cells(
    extent: usize,
    pad_leading: usize,
    pad_trailing: usize,
    cell: usize,
) -> usize {
    let cell = cell.max(1);
    extent
        .saturating_sub(pad_leading.saturating_add(pad_trailing))
        .checked_div(cell)
        .unwrap_or(0)
        .max(1)
}

#[cfg_attr(
    any(test, debug_assertions),
    aterm_spec_anchor::refines(
        machine = "VisiblePadCrop",
        action = "Crop",
        project = "aterm_gui::project_visible_pad_crop"
    )
)]
fn crop_visible_frame(frame: &mut Frame, crop_top: usize, pad: usize, pad_top: usize) {
    let removed = pad.saturating_sub(pad_top);
    if removed == 0 || frame.height == 0 || frame.width == 0 {
        return;
    }
    let crop_top = crop_top.min(removed).min(frame.height);
    let visible_height = visible_frame_height(frame.height, pad, pad_top);
    let start = crop_top.saturating_mul(frame.width);
    let len = visible_height.saturating_mul(frame.width);
    let end = start.saturating_add(len).min(frame.pixels.len());
    if start < end && start != 0 {
        frame.pixels.copy_within(start..end, 0);
    }
    frame.pixels.truncate(end.saturating_sub(start));
    frame.height = visible_height;
}

#[cfg(test)]
#[allow(
    clippy::too_many_arguments,
    reason = "named scalar projection mirrors the derived model variables exactly"
)]
fn project_visible_pad_crop(
    pad: usize,
    request: usize,
    rendered_top: usize,
    visible_top: usize,
    grid: usize,
    head: usize,
    raw_height: usize,
    visible_height: usize,
) -> std::collections::BTreeMap<&'static str, i64> {
    let raw_pad_bottom = raw_height.saturating_sub(grid + head + rendered_top);
    let visible_pad_bottom = visible_height.saturating_sub(grid + head + rendered_top);
    [
        ("phase", 2),
        ("pad", pad as i64),
        ("request", request as i64),
        ("grid", grid as i64),
        ("head", head as i64),
        ("pad_top", rendered_top as i64),
        ("raw_pad_bottom", raw_pad_bottom as i64),
        ("raw_height", raw_height as i64),
        ("visible_pad_top", visible_top as i64),
        ("visible_pad_bottom", visible_pad_bottom as i64),
        ("visible_height", visible_height as i64),
        (
            "crop_total",
            raw_height.saturating_sub(visible_height) as i64,
        ),
    ]
    .into_iter()
    .collect()
}

fn try_shift_window_absolute_effects_y(input: &mut RenderInput, delta: i32) -> bool {
    let translated = |value: u16| {
        i32::from(value)
            .checked_add(delta)
            .and_then(|value| u16::try_from(value).ok())
    };
    let edge_ok = |edge: i32| {
        let moved = i64::from(edge) + i64::from(delta);
        edge == i32::MIN
            || edge == i32::MAX
            || (i64::from(i32::MIN) < moved && moved < i64::from(i32::MAX))
    };
    let rect_ok = |r: &aterm_core::render::PxRect| edge_ok(r.y0) && edge_ok(r.y1);
    let fx_valid = input
        .fx_layers
        .iter()
        .filter(|layer| layer.space == aterm_core::render::FxSpace::Window)
        .all(|layer| layer.offset.1.checked_add(delta).is_some() && rect_ok(&layer.clip))
        && input.fx_occluders.iter().all(rect_ok);
    let valid = input
        .cursor_glow_add
        .iter()
        .chain(input.glow_under.iter())
        .all(|quad| translated(quad.y).is_some())
        && input
            .glow_halo
            .iter()
            .all(|halo| translated(halo.y).is_some() && translated(halo.cy).is_some())
        && input
            .fire_patch
            .iter()
            .all(|patch| translated(patch.y).is_some() && translated(patch.base_y).is_some());
    if !(valid && fx_valid) {
        return false;
    }
    let shift = |value: &mut u16| {
        *value = translated(*value).expect("effect shift preflighted");
    };
    for quad in input
        .cursor_glow_add
        .iter_mut()
        .chain(input.glow_under.iter_mut())
    {
        shift(&mut quad.y);
    }
    for halo in &mut input.glow_halo {
        shift(&mut halo.y);
        shift(&mut halo.cy);
    }
    for patch in &mut input.fire_patch {
        shift(&mut patch.y);
        shift(&mut patch.base_y);
    }
    for layer in &mut input.fx_layers {
        if layer.space == aterm_core::render::FxSpace::Window {
            layer.offset.1 += delta;
            layer.clip = layer.clip.translate(0, delta);
        }
    }
    for occluder in &mut input.fx_occluders {
        *occluder = occluder.translate(0, delta);
    }
    true
}

