#[allow(
    clippy::large_enum_variant,
    reason = "same trade-off as Backend itself: Ready is the lifetime-resident common path; boxing it would add a per-frame indirection"
)]
enum BackendSlot {
    Pending(Option<std::thread::JoinHandle<(Backend, bool, Option<String>)>>),
    Ready(Backend),
}

impl BackendSlot {
    fn ready(&self) -> &Backend {
        match self {
            BackendSlot::Ready(b) => b,
            BackendSlot::Pending(_) => {
                panic!("backend used before attach_os_window joined the build (ordering bug)")
            }
        }
    }

    fn ready_mut(&mut self) -> &mut Backend {
        match self {
            BackendSlot::Ready(b) => b,
            BackendSlot::Pending(_) => {
                panic!("backend used before attach_os_window joined the build (ordering bug)")
            }
        }
    }

    const fn is_pending(&self) -> bool {
        matches!(self, BackendSlot::Pending(_))
    }

    fn swap_renderer(&mut self, next: Backend) {
        let (pad, pad_top, head) = (self.pad(), self.pad_top(), self.head());
        *self = BackendSlot::Ready(next);
        self.set_pad(pad);
        self.set_pad_top(pad_top);
        self.set_head(head);
    }

    fn cell_size(&self) -> (usize, usize) {
        self.ready().cell_size()
    }

    fn pad(&self) -> usize {
        self.ready().pad()
    }

    fn set_pad(&mut self, pad: usize) {
        self.ready_mut().set_pad(pad);
    }

    fn pad_top(&self) -> usize {
        self.ready().pad_top()
    }

    fn set_pad_top(&mut self, pad_top: usize) {
        self.ready_mut().set_pad_top(pad_top);
    }

    fn head(&self) -> usize {
        self.ready().head()
    }

    fn set_head(&mut self, head: usize) {
        self.ready_mut().set_head(head);
    }

    fn set_chrome_bleed(&mut self, bleed: Option<aterm_render::ChromeBleed>) {
        self.ready_mut().set_chrome_bleed(bleed);
    }

    fn chrome_bleed(&self) -> Option<aterm_render::ChromeBleed> {
        self.ready().chrome_bleed()
    }

    fn activate_px(&mut self, px: f32) {
        self.ready_mut().activate_px(px);
    }

    fn pin_glyph_raster_knobs(&mut self, knobs: &app_config::GlyphRasterKnobs) {
        self.ready_mut().pin_glyph_raster_knobs(knobs);
    }

    fn glyph_cache_len(&self) -> usize {
        self.ready().glyph_cache_len()
    }

    fn cell_geometry(&self, px: f32) -> (usize, usize, i32) {
        self.ready().cell_geometry(px)
    }

    fn band_room(&mut self) -> (usize, usize) {
        self.ready_mut().band_room()
    }

    #[cfg(any(windows, target_os = "linux"))]
    fn deco_metrics_for(&self, px: f32) -> aterm_render::deco::DecoMetrics {
        self.ready().deco_metrics_for(px)
    }

    fn fallback_parse_pending(&mut self) -> bool {
        self.ready_mut().fallback_parse_pending()
    }

    fn frame_size(&self, rows: usize, cols: usize) -> (usize, usize) {
        self.ready().frame_size(rows, cols)
    }

    fn raw_frame_size(&self, rows: usize, cols: usize) -> (usize, usize) {
        self.ready().raw_frame_size(rows, cols)
    }

    fn configure_gpu_visible_y(
        &mut self,
        rows: usize,
        cols: usize,
        destination_height: usize,
    ) -> usize {
        self.ready_mut()
            .configure_gpu_visible_y(rows, cols, destination_height)
    }

    fn set_cursor_blink_phase(&mut self, on: bool) {
        self.ready_mut().set_cursor_blink_phase(on);
    }

    fn set_cursor_style_override(&mut self, style: Option<CursorStyle>) {
        self.ready_mut().set_cursor_style_override(style);
    }

    fn set_text_shaping(&mut self, shaping: aterm_render::TextShapingConfig) {
        self.ready_mut().set_text_shaping(shaping);
    }

    fn set_text_blending(&mut self, mode: aterm_render::TextBlending) {
        self.ready_mut().set_text_blending(mode);
    }

    fn set_font_thicken(&mut self, on: bool) {
        self.ready_mut().set_font_thicken(on);
    }

    fn set_stem_gamma(&mut self, gamma: f32) {
        self.ready_mut().set_stem_gamma(gamma);
    }

    fn set_font_hinting(&mut self, mode: &str) {
        self.ready_mut().set_font_hinting(mode);
    }

    fn set_font_subpixel(&mut self, mode: &str) {
        self.ready_mut().set_font_subpixel(mode);
    }

    fn set_selection_inactive(&mut self, inactive: bool) {
        self.ready_mut().set_selection_inactive(inactive);
    }

    fn admitted_font_sources(&self) -> Option<aterm_render::AdmittedFontSources> {
        match self {
            Self::Pending(_) => None,
            Self::Ready(backend) => Some(backend.admitted_font_sources()),
        }
    }

    fn drawn_faces(&self) -> Option<&aterm_render::DrawnFaces> {
        match self {
            Self::Pending(_) => None,
            Self::Ready(backend) => backend.drawn_faces(),
        }
    }

    fn rebuild_font_from_admitted(&mut self, px: f32, theme: Theme) -> Result<(), String> {
        self.ready_mut().rebuild_font_from_admitted(px, theme)
    }

    fn cpu_renderer_from_admitted(&self, px: f32, theme: Theme) -> Result<Renderer, String> {
        self.ready().cpu_renderer_from_admitted(px, theme)
    }

    fn seal_admitted_font_sources(&mut self) {
        let _ = self.ready_mut().seal_admitted_font_sources();
    }

    fn set_line_height(&mut self, scale: f32) {
        self.ready_mut().set_line_height(scale);
    }

    fn set_minimum_contrast(&mut self, ratio: f32) {
        self.ready_mut().set_minimum_contrast(ratio);
    }

    fn set_background_opacity(&mut self, opacity: f32) {
        self.ready_mut().set_background_opacity(opacity);
    }

    fn set_selection_fg(&mut self, fg: Option<u32>) {
        self.ready_mut().set_selection_fg(fg);
    }

    fn set_adjust_baseline(&mut self, px: i32) {
        self.ready_mut().set_adjust_baseline(px);
    }

    fn set_adjust_underline(&mut self, pos_px: i32, thick_px: i32) {
        self.ready_mut().set_adjust_underline(pos_px, thick_px);
    }

    fn set_underline_skip_descenders(&mut self, on: bool) {
        self.ready_mut().set_underline_skip_descenders(on);
    }

    fn unsupported_user_feature_tags(&self) -> Vec<[u8; 4]> {
        self.ready().unsupported_user_feature_tags()
    }

    fn render_input_for_destination(
        &mut self,
        gpu_scratch: &mut aterm_gpu::WindowGpu,
        input: &mut RenderInput,
        tray: Option<aterm_gpu::TrayQuad<'_>>,
        destination_height: Option<usize>,
    ) -> Result<Frame, String> {
        self.ready_mut()
            .render_input_for_destination(gpu_scratch, input, tray, destination_height)
    }

    fn is_gpu(&self) -> bool {
        self.ready().is_gpu()
    }

    fn gpu_mut(&mut self) -> Option<&mut aterm_gpu::GpuRenderer> {
        self.ready_mut().gpu_mut()
    }

    fn gpu_ref(&self) -> Option<&aterm_gpu::GpuRenderer> {
        self.ready().gpu_ref()
    }
}

/// The two occupants of a session's single drive-lease slot ([`SessionCtx::turn_lease`]).
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum Lease {
    Turn {
        id: u64,
        driver: Option<SessionId>,
        typing: bool,
    },
    Drive {
        holder: String,
        expires_us: u64,
        conn: Option<u64>,
        hard: bool,
        here: bool,
        holder_pid: Option<u32>,
    },
}

impl Lease {
    /// What this lease refuses a write verb from connection `conn` with at `now_us`.
    #[must_use]
    pub(crate) fn write_block(&self, now_us: u64, conn: Option<u64>) -> Option<String> {
        match self {
            Lease::Turn { id, .. } => Some(format!("turn={id}")),
            Lease::Drive {
                holder,
                expires_us,
                conn: held_by,
                hard: true,
                ..
            } if *expires_us > now_us && *held_by != conn => Some(format!("lease={holder}")),
            Lease::Drive { .. } => None,
        }
    }

    /// Whether this is a live drive lease taken over connection `conn`.
    #[must_use]
    pub(crate) fn held_over(&self, now_us: u64, conn: Option<u64>) -> bool {
        matches!(self, Lease::Drive { expires_us, conn: Some(held_by), .. }
            if *expires_us > now_us && Some(*held_by) == conn)
    }

    /// Whether this lease still blocks a new lease/`turn` acquisition at `now_us`.
    #[must_use]
    pub const fn is_live(&self, now_us: u64) -> bool {
        match self {
            Lease::Turn { .. } => true,
            Lease::Drive { expires_us, .. } => *expires_us > now_us,
        }
    }

    /// Whether a driver may still type into the session at `now_us` (a `turn` before settle, or a live drive lease).
    #[must_use]
    pub(crate) const fn driver_may_type(&self, now_us: u64) -> bool {
        match self {
            Lease::Turn { typing, .. } => *typing,
            Lease::Drive { expires_us, .. } => *expires_us > now_us,
        }
    }

    /// The `who`/`lease status` `driving=` token for a live lease at `now_us`, or `None` once it has lapsed.
    #[must_use]
    pub(crate) fn driving_token(&self, now_us: u64) -> Option<String> {
        match self {
            Lease::Turn { id, .. } => Some(id.to_string()),
            Lease::Drive {
                holder, expires_us, ..
            } if *expires_us > now_us => Some(format!("lease:{holder}")),
            Lease::Drive { .. } => None,
        }
    }
}

