struct Session {
    id: u64,
    term: Arc<Mutex<Terminal>>,
    adopt_pulse_hold: Arc<std::sync::atomic::AtomicBool>,
    master: i32,
    pid: i32,
    child_reaped: std::sync::atomic::AtomicBool,
    shell_identity: aterm_pty::ShellIdentity,
    child_exit: std::sync::OnceLock<aterm_pty::ChildExit>,
    exit_watch: Option<aterm_uds::exitwatch::ExitWatch>,
    shell_start: Option<crate::spawn::ShellStart>,
    pty_closed_at: Arc<std::sync::OnceLock<Instant>>,
    handoff_local_id: Option<u64>,
    journal_key: Option<(u32, u64)>,
    handoff_commit: Option<Arc<crate::shell_rekey::Deferred>>,
    frozen_path: bool,
    rekey_channel: bool,
    body_loader: bool,
    integration_frozen: bool,
    ctx: Arc<SessionCtx>,
    child_proxy: Option<crate::proxy::ChildProxy>,
    output_wake_pending: Arc<AtomicU64>,
    last_output_ns: Arc<AtomicU64>,
    output_request_booked_ns: AtomicU64,
    latest_output_activity_ns: Arc<AtomicU64>,
    reader_join: Option<std::thread::JoinHandle<()>>,
    wake_wr: i32,
    reader_stop: Arc<AtomicBool>,
    reflow_cancel: Arc<AtomicBool>,
    pub(crate) fg_holder: Arc<std::sync::atomic::AtomicI32>,
    temporal_writer_join: Option<std::thread::JoinHandle<()>>,
    handoff_history: Option<crate::handoff_history::AdoptedHistory>,
    _pty_census: crate::metrics::PtyCensus,
}

impl Session {
    fn reap_child(&self) -> Option<aterm_pty::ChildExit> {
        let collected = if self.shell_identity.own_child {
            aterm_pty::collect_exit_status(self.pid)
        } else {
            self.exit_watch
                .as_ref()
                .and_then(aterm_uds::exitwatch::ExitWatch::exit_status)
                .and_then(crate::spawn::child_exit_of_wait_status)
        };
        if let Some(exit) = collected {
            self.child_reaped
                .store(true, std::sync::atomic::Ordering::Release);
            let _ = self.child_exit.set(exit);
        }
        collected
    }

    fn predecessor_owns(&self) -> bool {
        self.handoff_commit
            .as_ref()
            .is_some_and(|commit| commit.withdraw(&self.ctx.self_id))
    }

    fn hang_up_and_reap(&self, predecessor_owns: bool) {
        if predecessor_owns || self.child_reaped.load(std::sync::atomic::Ordering::Acquire) {
            return;
        }
        let _ = aterm_pty::hangup_shell(&self.shell_identity, self.master);
        aterm_pty::reap_shell_in_background(self.shell_identity);
    }
}

impl Drop for Session {
    fn drop(&mut self) {
        crate::keeper_link::release(self.id);
        drop(self.child_proxy.take());
        self.ctx.fabric.close();
        let predecessor_owns = self.predecessor_owns();
        if self.rekey_channel && !predecessor_owns {
            crate::shell_rekey::discard(&self.ctx.self_id);
        }
        if self.body_loader && !predecessor_owns {
            crate::shell_body::discard(&self.ctx.self_id);
        }
        crate::shell_rekey::forget_typed(&self.ctx.self_id);
        self.hang_up_and_reap(predecessor_owns);
        drop(self.ctx.witness.take_fifo());
        self.ctx.sink.sever_input();
        if self.wake_wr >= 0 {
            aterm_pty::wake(self.wake_wr);
            aterm_pty::close_fd(self.wake_wr);
            self.wake_wr = -1;
        }
        self.reader_stop
            .store(true, std::sync::atomic::Ordering::Release);
        self.reflow_cancel
            .store(true, std::sync::atomic::Ordering::Release);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TabIndex {
    active: usize,
    count: usize,
}

impl TabIndex {
    const fn new(active: usize, count: usize) -> Self {
        TabIndex { active, count }
    }

    const fn add(&mut self) -> usize {
        self.count += 1;
        self.active = self.count - 1;
        self.active
    }

    const fn switch_to(&mut self, i: usize) -> usize {
        if i < self.count {
            self.active = i;
        }
        self.active
    }

    const fn cycle(&mut self, forward: bool) -> usize {
        if self.count <= 1 {
            return self.active;
        }
        self.active = if forward {
            (self.active + 1) % self.count
        } else {
            (self.active + self.count - 1) % self.count
        };
        self.active
    }

    const fn close(&mut self, i: usize) -> bool {
        // Distinct branch.
        if i >= self.count {
            // Distinct branch.
            return false; // out of range: nothing to close
        }
        if self.count <= 1 {
            // Distinct branch.
            return true; // closing the last tab → exit the app
        }
        self.count -= 1;
        if i < self.active {
            self.active -= 1;
        } else if self.active >= self.count {
            self.active = self.count - 1;
        }
        false
    }
}

fn register_terminal_tab(
    tab_ids: &mut tab_model::IdAllocator<tab_model::TabId>,
    views: &mut tab_model::ViewStore,
    layout: &pane::PaneTree,
) -> Result<tab_model::Tab, tab_model::IdExhausted> {
    let tab_id = tab_ids.allocate()?;
    let mut registered = Vec::with_capacity(layout.len());
    for session in layout.sessions() {
        match views.insert_terminal(session) {
            Ok(view) => registered.push((session, view)),
            Err(error) => {
                for (_, view) in registered {
                    views.remove(view);
                }
                return Err(error);
            }
        }
    }
    let by_session: HashMap<u64, tab_model::ViewId> = registered.iter().copied().collect();
    let root = layout.map_sessions(|session| by_session[&session]);
    let focus = by_session[&layout.focus()];
    Ok(tab_model::Tab::from_root(
        tab_id,
        root,
        focus,
        layout.is_zoomed(),
        tab_model::TabPresentation::terminal("aterm"),
    ))
}

#[derive(Default)]
struct SessionPool {
    sessions: std::collections::HashMap<u64, PooledSession>,
    insert_epoch: u64,
}

struct PooledSession {
    session: Session,
    views: u32,
    rain_override: Option<bool>,
    theme: Option<session_theme::SessionTheme>,
    own_colors: Option<Arc<aterm_core::config::TerminalConfig>>,
    focus_arms_told: u32,
}

impl SessionPool {
    fn insert(&mut self, session: Session) -> u64 {
        let id = session.id;
        self.insert_epoch = self.insert_epoch.wrapping_add(1);
        let focus_arms_told = session.ctx.modes.focus_arms();
        self.sessions.insert(
            id,
            PooledSession {
                session,
                views: 1,
                rain_override: None,
                theme: None,
                own_colors: None,
                focus_arms_told,
            },
        );
        id
    }
    fn focus_arms_told(&self, id: u64) -> Option<u32> {
        self.sessions.get(&id).map(|p| p.focus_arms_told)
    }
    fn set_focus_arms_told(&mut self, id: u64, arms: u32) {
        if let Some(p) = self.sessions.get_mut(&id) {
            p.focus_arms_told = arms;
        }
    }
    fn rain_override(&self, id: u64) -> Option<bool> {
        self.sessions.get(&id).and_then(|p| p.rain_override)
    }
    fn set_rain_override(&mut self, id: u64, over: Option<bool>) {
        if let Some(p) = self.sessions.get_mut(&id) {
            p.rain_override = over;
        }
    }
    fn theme(&self, id: u64) -> Option<&session_theme::SessionTheme> {
        self.sessions.get(&id).and_then(|p| p.theme.as_ref())
    }
    fn set_theme(&mut self, id: u64, theme: Option<session_theme::SessionTheme>) {
        if let Some(p) = self.sessions.get_mut(&id) {
            p.theme = theme;
        }
    }
    fn own_colors(&self, id: u64) -> Option<&Arc<aterm_core::config::TerminalConfig>> {
        self.sessions.get(&id).and_then(|p| p.own_colors.as_ref())
    }
    fn set_own_colors(&mut self, id: u64, colors: Option<Arc<aterm_core::config::TerminalConfig>>) {
        if let Some(p) = self.sessions.get_mut(&id) {
            p.own_colors = colors;
        }
    }
    fn ids(&self) -> Vec<u64> {
        self.sessions.keys().copied().collect()
    }
    fn get(&self, id: u64) -> Option<&Session> {
        self.sessions.get(&id).map(|p| &p.session)
    }
    #[cfg(unix)]
    fn hang_up_at_exit(&self) {
        for pooled in self.sessions.values() {
            let session = &pooled.session;
            session.hang_up_and_reap(session.predecessor_owns());
        }
    }
    fn predecessors_sessions(&self) -> Vec<SessionId> {
        self.sessions
            .values()
            .map(|pooled| &pooled.session)
            .filter(|session| session.predecessor_owns())
            .map(|session| session.ctx.self_id.clone())
            .collect()
    }
    #[cfg_attr(
        any(test, debug_assertions),
        aterm_spec_anchor::refines(
            machine = "session_pool",
            action = "Acquire",
            project = "aterm_gui::session_pool_conformance::project"
        )
    )]
    fn attach(&mut self, id: u64) {
        if let Some(p) = self.sessions.get_mut(&id) {
            p.views += 1;
        }
    }
    fn views(&self, id: u64) -> Option<u32> {
        self.sessions.get(&id).map(|p| p.views)
    }
    fn any_shared(&self) -> bool {
        self.sessions.values().any(|p| p.views > 1)
    }
    fn drops_of(&self, ids: &[u64]) -> Vec<bool> {
        let mut left: HashMap<u64, Option<u32>> = HashMap::new();
        ids.iter()
            .map(|id| {
                let slot = left.entry(*id).or_insert_with(|| self.views(*id));
                let now = slot.map(|n| n.saturating_sub(1));
                *slot = now.filter(|n| *n > 0);
                now == Some(0)
            })
            .collect()
    }
    #[cfg_attr(
        any(test, debug_assertions),
        aterm_spec_anchor::refines(
            machine = "session_pool",
            action = "Release",
            project = "aterm_gui::session_pool_conformance::project"
        )
    )]
    fn detach(&mut self, id: u64) -> bool {
        if let Some(p) = self.sessions.get_mut(&id) {
            p.views = p.views.saturating_sub(1);
            if p.views == 0 {
                self.sessions.remove(&id);
                return true;
            }
        }
        false
    }
    fn iter(&self) -> impl Iterator<Item = &Session> {
        self.sessions.values().map(|p| {
            #[cfg(test)]
            wake_census::note_pool_visit();
            &p.session
        })
    }
    const fn insert_epoch(&self) -> u64 {
        self.insert_epoch
    }
    #[cfg(unix)]
    fn take_handoff_histories(&mut self) -> Vec<crate::handoff_history::ImportJob> {
        self.sessions
            .values_mut()
            .filter_map(|p| {
                let history = p.session.handoff_history.take()?;
                Some(crate::handoff_history::ImportJob {
                    session: p.session.id,
                    term: Arc::clone(&p.session.term),
                    history,
                })
            })
            .collect()
    }
}

