const PRESENT_RETRY_BASE: Duration = Duration::from_millis(16);
const PRESENT_RETRY_CAP: u8 = 5;

#[must_use]
const fn autonomous_retry(reason: metrics::PresentDropReason) -> bool {
    matches!(
        reason,
        metrics::PresentDropReason::GpuReconfigured
            | metrics::PresentDropReason::GpuTimeout
            | metrics::PresentDropReason::GpuUnavailable
            | metrics::PresentDropReason::CpuResize
            | metrics::PresentDropReason::CpuAcquire
            | metrics::PresentDropReason::CpuCommit
    )
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct PresentRetry {
    autonomous_retries: u8,
    deadline: Option<Instant>,
    parked: bool,
    recovery_redraw_outstanding: bool,
}

impl PresentRetry {
    fn on_drop(&mut self, reason: metrics::PresentDropReason, now: Instant) -> Option<Instant> {
        self.on_drop_with_bootstrap(reason, now, false)
    }

    fn bootstrap_drop_allowed(&self) -> bool {
        *self == Self::default()
    }

    fn on_bootstrap_drop(
        &mut self,
        reason: metrics::PresentDropReason,
        now: Instant,
    ) -> Option<Instant> {
        self.on_drop_with_bootstrap(reason, now, true)
    }

    fn on_drop_with_bootstrap(
        &mut self,
        reason: metrics::PresentDropReason,
        now: Instant,
        before_first_present: bool,
    ) -> Option<Instant> {
        let bootstrap_occluded = before_first_present
            && reason == metrics::PresentDropReason::GpuOccluded
            && *self == Self::default();
        self.deadline = None;
        self.recovery_redraw_outstanding = false;
        if (autonomous_retry(reason) || bootstrap_occluded)
            && self.autonomous_retries < PRESENT_RETRY_CAP
        {
            let shift = u32::from(self.autonomous_retries);
            let factor = 1u32 << shift;
            const RECONFIGURE_FAST_RETRY: std::time::Duration = std::time::Duration::from_millis(1);
            let delay = if self.autonomous_retries == 0
                && (reason == metrics::PresentDropReason::GpuReconfigured || bootstrap_occluded)
            {
                RECONFIGURE_FAST_RETRY
            } else {
                PRESENT_RETRY_BASE.saturating_mul(factor)
            };
            self.autonomous_retries += 1;
            let deadline = now + delay;
            self.deadline = Some(deadline);
            self.parked = false;
            Some(deadline)
        } else {
            self.parked = true;
            None
        }
    }

    fn take_due(&mut self, now: Instant) -> bool {
        if self.deadline.is_some_and(|deadline| now >= deadline) {
            self.deadline = None;
            self.recovery_redraw_outstanding = true;
            true
        } else {
            false
        }
    }

    const fn present_attempt_allowed(&self) -> bool {
        self.deadline.is_none() && !self.parked
    }

    fn on_presented(&mut self) {
        *self = Self::default();
    }

    fn on_recovery_redraw_requested(&mut self) {
        *self = Self {
            recovery_redraw_outstanding: true,
            ..Self::default()
        };
    }

    const fn on_recovery_redraw_serviced(&mut self) {
        self.recovery_redraw_outstanding = false;
    }

    #[must_use = "an unresolved recovery episode must schedule a redraw"]
    fn on_external_stimulus(&mut self) -> bool {
        let recovery_unresolved = *self != Self::default();
        let redraw_outstanding = self.recovery_redraw_outstanding;
        *self = Self::default();
        self.recovery_redraw_outstanding = redraw_outstanding;
        recovery_unresolved
    }
}

fn frame_cap_due(
    redraw_pending: bool,
    last_present_at: Option<Instant>,
    pace_floor: Duration,
    now: Instant,
) -> bool {
    redraw_pending
        && last_present_at.is_some_and(|presented| now.duration_since(presented) >= pace_floor)
}

fn service_due_presentation_clocks(
    acquire_pending: bool,
    retry: &mut PresentRetry,
    redraw_pending: &mut bool,
    last_present_at: Option<Instant>,
    pace_floor: Duration,
    now: Instant,
) -> bool {
    if acquire_pending {
        return false;
    }
    let retry_due = retry.take_due(now);
    let cap_due = frame_cap_due(*redraw_pending, last_present_at, pace_floor, now);
    if cap_due {
        *redraw_pending = false;
    }
    retry_due || cap_due
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PresentDropAccounting {
    Count,
    Update,
}

#[must_use]
fn rearm_failed_gpu_recovery(
    retry: &mut PresentRetry,
    source_drop_already_counted: bool,
    now: Instant,
) -> (PresentDropAccounting, bool) {
    let parked = retry
        .on_drop(metrics::PresentDropReason::CpuAcquire, now)
        .is_none();
    let accounting = if source_drop_already_counted {
        PresentDropAccounting::Update
    } else {
        PresentDropAccounting::Count
    };
    (accounting, parked)
}

fn request_recovery_redraw(retry: &mut PresentRetry, request_redraw: impl FnOnce()) {
    retry.on_recovery_redraw_requested();
    request_redraw();
}

fn request_gpu_recovery_redraw<W: ?Sized>(
    retry: &mut PresentRetry,
    window: Option<&W>,
    request_redraw: impl FnOnce(&W),
) -> bool {
    let Some(window) = window else {
        return false;
    };
    request_recovery_redraw(retry, || request_redraw(window));
    true
}

#[must_use = "the caller should account for whether a redraw was delivered"]
fn rearm_present_and_request(
    retry: &mut PresentRetry,
    request_even_if_ready: bool,
    request_redraw: impl FnOnce(),
) -> bool {
    let was_gated = retry.on_external_stimulus();
    let requested = was_gated || request_even_if_ready;
    if requested {
        retry.recovery_redraw_outstanding = true;
        request_redraw();
    }
    requested
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct GpuAcquireWait {
    pending_surface: Option<u64>,
}

impl GpuAcquireWait {
    const fn begin(&mut self, surface: u64) {
        self.pending_surface = Some(surface);
    }

    fn waiting_for(&self, current_surface: Option<u64>) -> bool {
        current_surface.is_some() && self.pending_surface == current_surface
    }

    fn complete(&mut self, current_surface: Option<u64>, reported_surface: u64) -> bool {
        if current_surface != Some(reported_surface) || !self.waiting_for(current_surface) {
            return false;
        }
        self.pending_surface = None;
        true
    }
}

