fn active_terminal_projection<'a>(
    ws: &'a WindowState,
    views: &tab_model::ViewStore,
) -> Option<&'a pane::PaneTree> {
    let tab = ws.tab_set.active()?;
    tab.root
        .leaves()
        .into_iter()
        .all(|view| matches!(views.get(view), Some(tab_model::View::Terminal(_))))
        .then(|| ws.layouts.get(ws.tabs.active))
        .flatten()
}

fn active_tab_displays_session(
    ws: &WindowState,
    views: &tab_model::ViewStore,
    session: u64,
) -> bool {
    ws.tab_set.active().is_some_and(|tab| {
        if tab.zoomed && tab.root.len() > 1 {
            return views
                .get(tab.focus)
                .copied()
                .and_then(tab_model::View::terminal_session)
                == Some(session);
        }
        tab.root.any_leaf(&mut |view| {
            views
                .get(*view)
                .copied()
                .and_then(tab_model::View::terminal_session)
                == Some(session)
        })
    })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct AutoApplyIntent {
    build: u64,
    dmg_sha256: [u8; 32],
    retry_at: Instant,
    attempts: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct AutoApplyLadder {
    build: u64,
    armed_at: Instant,
    announced: native_update_auto_intent::ApplyPhase,
    restored_hold_said: bool,
}

#[cfg(unix)]
#[derive(Clone, Debug, PartialEq, Eq)]
struct AutoApplyRosterWait {
    build: u64,
    dmg_sha256: [u8; 32],
    reason: String,
    reread_at: Instant,
    answered_at: Instant,
    rereading: bool,
    said: bool,
}

#[cfg(unix)]
impl AutoApplyRosterWait {
    fn covers(&self, build: u64, dmg_sha256: [u8; 32]) -> bool {
        self.build == build && self.dmg_sha256 == dmg_sha256
    }
}

#[cfg(unix)]
const ROSTER_WAIT_REREAD: Duration = Duration::from_secs(10 * 60);

#[cfg(unix)]
const ROSTER_WAIT_POLL: Duration = Duration::from_secs(2);

const AUTOMATIC_UPDATE_QUIET_EPOCH_NS: u64 = 500_000_000;
const AUTOMATIC_UPDATE_QUIET_EPOCH: Duration =
    Duration::from_nanos(AUTOMATIC_UPDATE_QUIET_EPOCH_NS);

const AUTOMATIC_UPDATE_ACTIVITY_GRACE: Duration = native_update_auto_intent::PREFER_IDLE_WINDOW;

const AUTOMATIC_UPDATE_KEYSTROKE_GAP: Duration = Duration::from_millis(2_500);

fn hands_off_keys(focused: bool, last_keystroke_at: Option<Instant>, now: Instant) -> bool {
    !focused
        || last_keystroke_at
            .is_none_or(|at| now.saturating_duration_since(at) >= AUTOMATIC_UPDATE_KEYSTROKE_GAP)
}

const fn os_window_focused(ws: &WindowState) -> bool {
    #[cfg(test)]
    if ws.os_window_for_test {
        return ws.focused;
    }
    ws.focused && ws.os_window.is_some()
}

/// True once the latest consumed PTY burst is old enough for automatic update admission.
#[inline]
pub(crate) const fn automatic_output_activity_quiet(now_ns: u64, latest_output_ns: u64) -> bool {
    latest_output_ns == 0
        || now_ns.saturating_sub(latest_output_ns) >= AUTOMATIC_UPDATE_QUIET_EPOCH_NS
}

/// A retry caused by activity must always be armed strictly after the poll that observed it.
#[inline]
pub(crate) fn automatic_update_activity_retry_at(now: Instant) -> Instant {
    now + AUTOMATIC_UPDATE_QUIET_EPOCH
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct AutoApplyManualOnly {
    build: u64,
    dmg_sha256: [u8; 32],
    activation: bool,
    retry_at: Option<std::time::Instant>,
}

impl AutoApplyManualOnly {
    #[cfg_attr(
        any(test, debug_assertions),
        aterm_spec_anchor::refines(
            machine = "NativeUpdateStructuralLatch",
            action = "ArmSameBuild",
            project = "aterm_gui::native_updater_conformance::project_structural_latch"
        )
    )]
    fn covers(self, build: u64, dmg_sha256: [u8; 32], activation: bool) -> bool {
        self.build == build && (self.activation || activation || self.dmg_sha256 == dmg_sha256)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct AutoApplyStructuralVerdict {
    build: u64,
    dmg_sha256: [u8; 32],
    activation: bool,
    resample_at: Option<std::time::Instant>,
    newer_spent: u64,
    newer_retry: Option<SupersedeRetry>,
    newer_refusals: u32,
    unmeasured_looks: u8,
    unmeasured_through: u64,
    unproven_looks: u8,
    unproven_through: u64,
    held_unmeasured: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SupersedeRetry {
    newer: u64,
    at: std::time::Instant,
}

impl AutoApplyStructuralVerdict {
    fn covers(self, build: u64, dmg_sha256: [u8; 32], activation: bool) -> bool {
        self.build == build && (self.activation || activation || self.dmg_sha256 == dmg_sha256)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct AutoOverlapRetry {
    build: u64,
    dmg_sha256: [u8; 32],
    activation: bool,
    cycles: u8,
    last_attempt: std::time::Instant,
}

impl AutoOverlapRetry {
    fn covers(self, build: u64, dmg_sha256: [u8; 32], activation: bool) -> bool {
        self.build == build && (self.activation || activation || self.dmg_sha256 == dmg_sha256)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct AutoApplyCaptureRefusal {
    build: u64,
    dmg_sha256: [u8; 32],
    activation: bool,
    desk: CaptureDesk,
    refused_at: std::time::Instant,
    refusals: u32,
    released: bool,
}

impl AutoApplyCaptureRefusal {
    fn covers(&self, build: u64, dmg_sha256: [u8; 32], activation: bool) -> bool {
        self.build == build && (self.activation || activation || self.dmg_sha256 == dmg_sha256)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CaptureDesk {
    sessions: Vec<(u64, Option<u64>)>,
}

impl CaptureDesk {
    fn from_readings(mut sessions: Vec<(u64, Option<u64>)>) -> Self {
        sessions.sort_unstable_by_key(|(id, _)| *id);
        Self { sessions }
    }

    fn unread(&self) -> usize {
        self.sessions
            .iter()
            .filter(|(_, reading)| reading.is_none())
            .count()
    }

    fn complete(&self) -> bool {
        self.unread() == 0
    }

    fn fill_from(&mut self, later: &Self) {
        for (id, reading) in &mut self.sessions {
            if reading.is_none() {
                *reading = later
                    .sessions
                    .binary_search_by_key(id, |(later_id, _)| *later_id)
                    .ok()
                    .and_then(|at| later.sessions[at].1);
            }
        }
    }

    fn moved_to(&self, later: &Self) -> bool {
        self.sessions.len() != later.sessions.len()
            || self
                .sessions
                .iter()
                .zip(&later.sessions)
                .any(|((id, was), (later_id, is))| {
                    id != later_id || matches!((was, is), (Some(was), Some(is)) if was != is)
                })
    }
}

#[derive(Clone, Debug)]
#[cfg(unix)]
struct HandoffPreverification {
    build: u64,
    commit: String,
    artifact: String,
    at: std::time::Instant,
    passed: bool,
    reason: Option<String>,
    policy: Option<aterm_update_core::handoff_policy::HandoffPolicy>,
    grant_chunks: bool,
}

#[cfg(unix)]
const HANDOFF_PREVERIFY_FRESHNESS: std::time::Duration = std::time::Duration::from_secs(10 * 60);

#[cfg(unix)]
const HANDOFF_PREVERIFY_READ_CEILING: std::time::Duration =
    aterm_update::HANDOFF_PREVERIFY_BOUND.saturating_add(HANDOFF_PREVERIFY_READ_MARGIN);

#[cfg(unix)]
const HANDOFF_PREVERIFY_READ_MARGIN: std::time::Duration = std::time::Duration::from_secs(2);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg(unix)]
struct HeldPersonApply {
    target_build: u64,
    until: std::time::Instant,
}

#[derive(Clone, Debug)]
#[cfg(unix)]
struct PreverifyInFlight {
    build: u64,
    commit: String,
    artifact: String,
    deadline: std::time::Instant,
    done: std::sync::Arc<std::sync::atomic::AtomicBool>,
    passing: std::sync::Arc<std::sync::OnceLock<PassingPreverification>>,
}

#[derive(Clone, Debug)]
#[cfg(unix)]
struct PassingPreverification {
    reason: String,
    ended: std::time::Instant,
}

#[cfg(unix)]
impl PreverifyInFlight {
    fn started(&self) -> std::time::Instant {
        self.deadline
            .checked_sub(HANDOFF_PREVERIFY_READ_CEILING)
            .unwrap_or(self.deadline)
    }

    fn running_for(&self, build: u64, now: std::time::Instant) -> bool {
        self.build == build
            && now < self.deadline
            && !self.done.load(std::sync::atomic::Ordering::Acquire)
    }

    fn reads(&self, attempt: &native_updater_service::ApplyAttemptTicket) -> bool {
        self.build == attempt.target_build()
            && self.commit == attempt.target_commit()
            && self.artifact == attempt.target_dmg_sha256()
    }

    fn ended_passing(&self, now: std::time::Instant) -> Option<&str> {
        self.ended_passing_at(now).map(|(reason, _)| reason)
    }

    fn ended_passing_at(&self, now: std::time::Instant) -> Option<(&str, std::time::Instant)> {
        if !self.done.load(std::sync::atomic::Ordering::Acquire) {
            return None;
        }
        self.passing
            .get()
            .filter(|passing| {
                now.saturating_duration_since(passing.ended) < HANDOFF_PREVERIFY_FRESHNESS
            })
            .map(|passing| (passing.reason.as_str(), passing.ended))
    }
}

