#[repr(u8)]
#[cfg(unix)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HandoffAttemptPhase {
    Waiting = 0,
    Committing = 1,
    Rejecting = 2,
}

#[repr(u8)]
#[cfg(unix)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HandoffReaperOwner {
    Unclaimed = 0,
    Worker = 1,
    Emergency = 2,
    Finished = 3,
}

#[derive(Debug)]
#[cfg(unix)]
struct HandoffAttemptArbiterInner {
    phase: std::sync::atomic::AtomicU8,
    reaper: std::sync::atomic::AtomicU8,
    turn_id_ceiling: std::sync::atomic::AtomicU64,
    connections_left_out: std::sync::OnceLock<Vec<session_store::ConnectionCarry>>,
}

#[derive(Clone, Debug)]
#[cfg(unix)]
struct HandoffAttemptArbiter(std::sync::Arc<HandoffAttemptArbiterInner>);

#[cfg(unix)]
impl HandoffAttemptArbiter {
    fn new() -> Self {
        Self(std::sync::Arc::new(HandoffAttemptArbiterInner {
            phase: std::sync::atomic::AtomicU8::new(HandoffAttemptPhase::Waiting as u8),
            reaper: std::sync::atomic::AtomicU8::new(HandoffReaperOwner::Unclaimed as u8),
            turn_id_ceiling: std::sync::atomic::AtomicU64::new(0),
            connections_left_out: std::sync::OnceLock::new(),
        }))
    }

    fn set_turn_id_ceiling(&self, ceiling: u64) {
        self.0
            .turn_id_ceiling
            .store(ceiling, std::sync::atomic::Ordering::Release);
    }

    fn turn_id_ceiling(&self) -> u64 {
        self.0
            .turn_id_ceiling
            .load(std::sync::atomic::Ordering::Acquire)
    }

    fn set_connections_left_out(&self, rows: Vec<session_store::ConnectionCarry>) {
        if !rows.is_empty() {
            let _ = self.0.connections_left_out.set(rows);
        }
    }

    fn connections_left_out(&self) -> &[session_store::ConnectionCarry] {
        self.0.connections_left_out.get().map_or(&[], Vec::as_slice)
    }

    fn phase(&self) -> HandoffAttemptPhase {
        match self.0.phase.load(std::sync::atomic::Ordering::Acquire) {
            value if value == HandoffAttemptPhase::Waiting as u8 => HandoffAttemptPhase::Waiting,
            value if value == HandoffAttemptPhase::Committing as u8 => {
                HandoffAttemptPhase::Committing
            }
            value if value == HandoffAttemptPhase::Rejecting as u8 => {
                HandoffAttemptPhase::Rejecting
            }
            _ => unreachable!("handoff attempt phase is written only by typed transitions"),
        }
    }

    fn try_begin_commit(&self) -> bool {
        self.0
            .phase
            .compare_exchange(
                HandoffAttemptPhase::Waiting as u8,
                HandoffAttemptPhase::Committing as u8,
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            )
            .is_ok()
    }

    fn try_begin_reject(&self) -> bool {
        self.0
            .phase
            .compare_exchange(
                HandoffAttemptPhase::Waiting as u8,
                HandoffAttemptPhase::Rejecting as u8,
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            )
            .is_ok()
    }

    fn commit_failed_to_rejecting(&self) -> bool {
        self.0
            .phase
            .compare_exchange(
                HandoffAttemptPhase::Committing as u8,
                HandoffAttemptPhase::Rejecting as u8,
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            )
            .is_ok()
    }

    fn claim_reaper(&self, owner: HandoffReaperOwner) -> bool {
        debug_assert!(matches!(
            owner,
            HandoffReaperOwner::Worker | HandoffReaperOwner::Emergency
        ));
        self.phase() == HandoffAttemptPhase::Rejecting
            && self
                .0
                .reaper
                .compare_exchange(
                    HandoffReaperOwner::Unclaimed as u8,
                    owner as u8,
                    std::sync::atomic::Ordering::AcqRel,
                    std::sync::atomic::Ordering::Acquire,
                )
                .is_ok()
    }

    fn finish_reap(&self, owner: HandoffReaperOwner) -> bool {
        self.0
            .reaper
            .compare_exchange(
                owner as u8,
                HandoffReaperOwner::Finished as u8,
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            )
            .is_ok()
    }

    #[cfg(test)]
    fn reaper_owner(&self) -> HandoffReaperOwner {
        match self.0.reaper.load(std::sync::atomic::Ordering::Acquire) {
            value if value == HandoffReaperOwner::Unclaimed as u8 => HandoffReaperOwner::Unclaimed,
            value if value == HandoffReaperOwner::Worker as u8 => HandoffReaperOwner::Worker,
            value if value == HandoffReaperOwner::Emergency as u8 => HandoffReaperOwner::Emergency,
            value if value == HandoffReaperOwner::Finished as u8 => HandoffReaperOwner::Finished,
            _ => unreachable!("handoff reaper owner is written only by typed transitions"),
        }
    }
}

#[derive(Debug)]
enum UpdateHandoffStartError {
    #[cfg(unix)]
    ActivityDeferred(String),
    Refused(String),
    Failed(String),
    #[cfg(unix)]
    ParkMissed(String),
    #[cfg(unix)]
    CaptureRefused(String),
    #[cfg(unix)]
    HeldForRead {
        target_build: u64,
        until: std::time::Instant,
        message: String,
    },
}

impl UpdateHandoffStartError {
    fn failed(message: impl Into<String>) -> Self {
        Self::Failed(message.into())
    }

    #[cfg(unix)]
    fn activity(message: impl Into<String>) -> Self {
        Self::ActivityDeferred(message.into())
    }

    fn refused(message: impl Into<String>) -> Self {
        Self::Refused(message.into())
    }

    #[cfg(unix)]
    fn park_missed(message: impl Into<String>) -> Self {
        Self::ParkMissed(message.into())
    }

    #[cfg(unix)]
    fn capture_refused(message: impl Into<String>) -> Self {
        Self::CaptureRefused(message.into())
    }

    #[cfg(unix)]
    fn held_for_read(
        target_build: u64,
        until: std::time::Instant,
        message: impl Into<String>,
    ) -> Self {
        Self::HeldForRead {
            target_build,
            until,
            message: message.into(),
        }
    }

    #[cfg(unix)]
    const fn is_activity_deferred(&self) -> bool {
        matches!(self, Self::ActivityDeferred(_))
    }

    const fn is_refused(&self) -> bool {
        matches!(self, Self::Refused(_))
    }

    #[cfg(unix)]
    const fn is_park_missed(&self) -> bool {
        matches!(self, Self::ParkMissed(_))
    }

    #[cfg(unix)]
    const fn is_capture_refused(&self) -> bool {
        matches!(self, Self::CaptureRefused(_))
    }

    #[cfg(unix)]
    const fn held_for_read_of(&self) -> Option<HeldPersonApply> {
        match self {
            Self::HeldForRead {
                target_build,
                until,
                ..
            } => Some(HeldPersonApply {
                target_build: *target_build,
                until: *until,
            }),
            _ => None,
        }
    }

    #[cfg(unix)]
    fn stops_routinely(&self, mode: crate::native_updater_service::ApplyMode) -> bool {
        self.is_activity_deferred()
            || ((self.is_park_missed() || self.is_capture_refused()) && mode.is_automatic())
    }

    fn into_message(self) -> String {
        match self {
            Self::Refused(message) | Self::Failed(message) => message,
            #[cfg(unix)]
            Self::ActivityDeferred(message)
            | Self::ParkMissed(message)
            | Self::CaptureRefused(message)
            | Self::HeldForRead { message, .. } => message,
        }
    }
}

impl std::fmt::Display for UpdateHandoffStartError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Refused(message) | Self::Failed(message) => formatter.write_str(message),
            #[cfg(unix)]
            Self::ActivityDeferred(message)
            | Self::ParkMissed(message)
            | Self::CaptureRefused(message)
            | Self::HeldForRead { message, .. } => formatter.write_str(message),
        }
    }
}

#[cfg(unix)]
type HandoffCommitFd = std::os::fd::OwnedFd;

#[cfg(unix)]
fn release_committed_readers(
    journal: Option<crash_journal::TakeOver>,
    gate: &spawn::DeferredReaderGate,
) {
    struct Release<'a>(&'a spawn::DeferredReaderGate);
    impl Drop for Release<'_> {
        fn drop(&mut self) {
            self.0.release();
        }
    }
    let release = Release(gate);
    crate::session_log_journal::commit_landed();
    if let Some(journal) = journal {
        journal.run(move || drop(release));
    }
}

#[cfg(unix)]
#[must_use]
fn handoff_proof_term(master: i32, device_term: bool) -> Option<i32> {
    if !device_term {
        // Inherited: `execve` copied the parent's descriptor table verbatim, so
        // the number is a value both sides compute and agree on.
        return Some(master);
    }
    #[cfg(target_os = "macos")]
    let term = handoff_rendezvous::pty_device_term(master);
    #[cfg(not(target_os = "macos"))]
    let term = None;
    term
}

